# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Timekeeping write delay test hook" do
  # A caller able to set the delay could slow every company's entry writes, so the
  # hook takes only the service token, like the relay pause hook.
  it "refuses to slow writes for a user token or a wrong service token and leaves no delay behind" do
    service_token = "service-#{SecureRandom.hex(24)}"
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => service_token
    ) do
      Timekeeping::TestHooks.clear_write_delay!
      user_token = mint_token({ sub: 7, company_id: 1, role: "owner" })
      body = JSON.generate({ "milliseconds" => 400 })

      [nil, "Bearer #{user_token}", "Bearer #{service_token}x"].each do |authorization|
        headers = { "Content-Type" => "application/json" }
        headers["Authorization"] = authorization if authorization
        post "/internal/v1/test-hooks/writes/delay", params: body, headers: headers

        expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }])
        expect(Timekeeping::TestHooks.write_delay_seconds.to_f).to eq(0.0)
      end
    end
  ensure
    Timekeeping::TestHooks.clear_write_delay!
  end
end
